async function capturePeriodic1x2(job) {
  const eventId = String(
    job?.event_id || ''
  ).trim();

  const url = String(
    job?.url || ''
  ).trim();

  if (!eventId || !url) {
    throw new Error(
      'Periodic odds job identity missing.'
    );
  }

  if (runningEvents.has(eventId)) {
    return {
      eventId,
      skipped: true,
      reason: 'already-running'
    };
  }

  runningEvents.add(eventId);

  try {
    const claimed =
      await markTrackingAttempt(eventId);

    if (!claimed) {
      return {
        eventId,
        skipped: true,
        reason: 'not-due-or-disabled'
      };
    }


    try {
      await backfill1x2Opening(eventId, url);
    } catch (openingError) {
      console.warn(
        '[odds-worker] 1X2 opening backfill failed ' + eventId + ': ' +
        openingError.message
      );
    }

    try {
      await backfillOverUnderOpening(
        eventId,
        url
      );
    } catch (openingError) {
      console.warn(
        `[odds-worker] O/U opening backfill failed ${eventId}: ${openingError.message}`
      );
    }

    try {
      await backfillAsianOpening(
        eventId,
        url
      );
    } catch (openingError) {
      console.warn(
        `[odds-worker] Asian opening backfill failed ${eventId}: ${openingError.message}`
      );
    }

    try {
      await backfillKgOpening(
        eventId,
        url
      );
    } catch (openingError) {
      console.warn(
        `[odds-worker] KG opening backfill failed ${eventId}: ${openingError.message}`
      );
    }

    if (!claimed) {
      return {
        eventId,
        skipped: true,
        reason: 'disabled-before-start'
      };
    }

    const [
      pulled1x2,
      pulledOverUnder,
      pulledAsian,
      pulledKg
    ] = await Promise.all([
      pull1x2WithFailover(url),
      pullOverUnderWithFailover(url),
      pullAsianWithFailover(url),
      pullKgWithFailover(url)
    ]);

    if (
      pulled1x2.eventId !== eventId
    ) {
      throw new Error(
        'Periodic 1X2 event mismatch.'
      );
    }

    if (
      pulledOverUnder.eventId !== eventId
    ) {
      throw new Error(
        'Periodic Over/Under event mismatch.'
      );
    }

    if (
      pulledAsian.eventId !== eventId
    ) {
      throw new Error(
        'Periodic Asian event mismatch.'
      );
    }

    if (
      pulledKg.eventId !== eventId
    ) {
      throw new Error(
        'Periodic KG event mismatch.'
      );
    }

    const rows1x2 =
      pulled1x2.rows.map(
        row => ({
          ...row,
          capturedAt:
            pulled1x2.capturedAt
        })
      );

    const rowsOverUnder =
      pulledOverUnder.rows.map(
        row => ({
          ...row,
          capturedAt:
            pulledOverUnder.capturedAt
        })
      );

    const rowsAsian =
      pulledAsian.rows.map(
        row => ({
          ...row,
          capturedAt:
            pulledAsian.capturedAt
        })
      );

    const rowsKg =
      pulledKg.rows.map(
        row => ({
          ...row,
          capturedAt:
            pulledKg.capturedAt
        })
      );

    const line15 =
      rowsOverUnder.filter(
        row =>
          Number(row.totalLine) === 1.5
      );

    const line25 =
      rowsOverUnder.filter(
        row =>
          Number(row.totalLine) === 2.5
      );

    if (
      !line15.length ||
      !line25.length
    ) {
      throw new Error(
        'Periodic Over/Under requires both 1.5 and 2.5.'
      );
    }

    if (!rowsAsian.length) {
      throw new Error(
        'Periodic Asian rows empty.'
      );
    }

    if (!rowsKg.length) {
      throw new Error(
        'Periodic KG rows empty.'
      );
    }

    const captureSequence =
      periodicSequence();

    const [
      saved1x2,
      savedOverUnder,
      savedAsian,
      savedKg
    ] = await Promise.all([
      saveOdds1x2Batch({
        eventId,
        rows: rows1x2,
        captureType: 'periodic',
        sourceName:
          pulled1x2.sourceName,
        sourceRegion:
          pulled1x2.sourceRegion,
        captureSequence
      }),

      saveOddsOverUnderBatch({
        eventId,
        rows: rowsOverUnder,
        captureType: 'periodic',
        sourceName:
          pulledOverUnder.sourceName,
        sourceRegion:
          pulledOverUnder.sourceRegion,
        captureSequence
      }),

      saveOddsAsianBatch({
        eventId,
        rows: rowsAsian,
        captureType: 'periodic',
        sourceName:
          pulledAsian.sourceName,
        sourceRegion:
          pulledAsian.sourceRegion,
        captureSequence
      }),

      saveOddsKgBatch({
        eventId,
        rows: rowsKg,
        captureType: 'periodic',
        sourceName:
          pulledKg.sourceName,
        sourceRegion:
          pulledKg.sourceRegion,
        captureSequence
      })
    ]);

    await markTrackingSuccess(
      eventId,
      captureSequence
    );

    return {
      eventId,
      skipped: false,

      fetched:
        rows1x2.length +
        rowsOverUnder.length +
        rowsAsian.length +
        rowsKg.length,

      inserted:
        saved1x2.inserted +
        savedOverUnder.inserted +
        savedAsian.inserted +
        savedKg.inserted,

      fetched1x2:
        rows1x2.length,
      inserted1x2:
        saved1x2.inserted,

      fetchedOverUnder:
        rowsOverUnder.length,
      insertedOverUnder:
        savedOverUnder.inserted,

      fetchedOverUnder15:
        line15.length,
      fetchedOverUnder25:
        line25.length,

      fetchedAsian:
        rowsAsian.length,
      insertedAsian:
        savedAsian.inserted,

      fetchedKg:
        rowsKg.length,
      insertedKg:
        savedKg.inserted,

      sourceName:
        pulled1x2.sourceName,
      sourceRegion:
        pulled1x2.sourceRegion,

      overUnderSourceName:
        pulledOverUnder.sourceName,
      overUnderSourceRegion:
        pulledOverUnder.sourceRegion,

      asianSourceName:
        pulledAsian.sourceName,
      asianSourceRegion:
        pulledAsian.sourceRegion,

      kgSourceName:
        pulledKg.sourceName,
      kgSourceRegion:
        pulledKg.sourceRegion,

      captureSequence
    };
  } catch (error) {
    await markTrackingFailure(
      eventId,
      error?.message || String(error)
    ).catch(() => {});

    throw error;
  } finally {
    runningEvents.delete(eventId);
  }
}
